SELECT

FROM joint_marketing_plan AS plan
WHERE plan.is_deleted = 0

    AND plan.name LIKE CONCAT('%', #{dto.name}, '%')


    AND plan.status = #{dto.status}


    AND plan.start_time >= #{dto.startTime}


    AND plan.end_time <= #{dto.endTime}

ORDER BY plan.created_time DESC

SELECT
,
participant.role AS planRole,
participant.join_time AS joinTime

FROM joint_marketing_plan AS plan
JOIN joint_marketing_participant AS participant ON plan.id = participant.plan_id

WHERE plan.is_deleted = 0 AND participant.is_deleted = 0 AND participant.merchant_id = #{merchantId}

    AND plan.name LIKE CONCAT('%', #{dto.name}, '%')


    AND plan.status = #{dto.status}


    AND plan.start_time >= #{dto.startTime}


    AND plan.end_time <= #{dto.endTime}


    AND plan.initiator_merchant_id IN

        #{id}



    AND participant.role = 'PARTICIPANT'


    AND participant.status = #{dto.acceptStatus}


    AND participant.created_time >= #{dto.acceptStartTime}


    AND participant.created_time <= #{dto.acceptEndTime}


ORDER BY participant.created_time DESC

SELECT COUNT(*) FROM joint_marketing_plan AS plan WHERE plan.is_deleted = 0
AND plan.name LIKE CONCAT('%', #{dto.name}, '%')
AND plan.status = #{dto.status}
